import { PythonIntValueError } from './errors.mjs';

const DECIMAL_INTEGER_PATTERN = /^[+-]?(?:\d+(?:_\d+)*)$/u;

export function parsePythonInt(literal) {
  const normalized = literal.trim();

  if (!DECIMAL_INTEGER_PATTERN.test(normalized)) {
    throw new PythonIntValueError(literal);
  }

  return BigInt(normalized.replaceAll('_', ''));
}

export function parseCommaSeparatedIntegers(text) {
  return text.split(',').map((part) => parsePythonInt(part));
}

