import { bucketize } from './lib/bucketize.mjs';
import { getProgramName, parseArgs } from './lib/cli.mjs';
import { PythonIntValueError } from './lib/errors.mjs';
import { parseCommaSeparatedIntegers } from './lib/python_int.mjs';
import { formatPythonValue } from './lib/python_repr.mjs';
import { formatPythonIntTraceback } from './lib/traceback.mjs';

export function main(argv = process.argv.slice(2), argv1 = process.argv[1]) {
  const programName = getProgramName(argv1);
  const parsed = parseArgs(argv, programName);

  if (parsed.kind === 'help') {
    process.stdout.write(parsed.text);
    return 0;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(parsed.text);
    return parsed.exitCode;
  }

  const numbers = parseCommaSeparatedIntegers(parsed.args.a);
  const result = bucketize(numbers, (value) => value % 2n === 0n);

  process.stdout.write(`${formatPythonValue(result)}\n`);
  return 0;
}

export function runCli() {
  try {
    process.exitCode = main();
  } catch (error) {
    if (error instanceof PythonIntValueError) {
      process.stderr.write(formatPythonIntTraceback(error.literal, process.pid));
      process.exitCode = 1;
      return;
    }

    throw error;
  }
}

runCli();

